ing:13px 14px;border-bottom:1px solid rgba(51,65,85,.45);font-size:12px;vertical-align:middle}.project-table tbody tr:last-child td{border-bottom:0}.project-row{background:#0d1424;transition:background .18s ease}.project-row:hover{background:#121c2e}.project-row.sortable-ghost{opacity:.28;background:#10203a}.project-row.sortable-chosen{box-shadow:0 12px 35px #0008}.project-number{width:30px;height:30px;border-radius:9px;background:#172554;color:#93c5fd;display:inline-flex;align-items:center;justify-content:center;font-size:12px;font-weight:900}.project-name{font-weight:800;font-size:13px;line-height:1.35;color:#f8fafc;min-width:220px}.project-client{font-weight:750;color:#e2e8f0;white-space:nowrap}.project-type{font-size:11px;color:#cbd5e1;white-space:nowrap}.status-badge{display:inline-flex;align-items:center;padding:4px 8px;border-radius:999px;font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;white-space:nowrap}.status-badge.ongoing{background:#052e2b;color:#6ee7b7;border:1px solid #065f46}.status-badge.completed{background:#172033;color:#94a3b8;border:1px solid #334155}.progress-cell{min-width:180px}.progress-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:7px}.progress-label{font-size:10px;color:#64748b;text-transform:uppercase;letter-spacing:.08em;font-weight:800}.progress-value{font-size:13px;font-weight:850;color:#7dd3fc}.progress-bar{height:7px;border-radius:99px;background:#1e293b;overflow:hidden}.progress-fill{height:100%;border-radius:99px;background:#38bdf8;transition:width .25s ease}.date-cell{white-space:nowrap;color:#cbd5e1;font-size:11px}.location-cell{max-width:210px;color:#94a3b8;font-size:11px}.location-text{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.drag-handle{display:inline-flex;align-items:center;justify-content:center;color:#64748b;font-size:17px;line-height:1;cursor:grab;touch-action:none;user-select:none}.drag-handle:active{cursor:grabbing}.actions{display:flex;align-items:center;justify-content:flex-end;gap:7px}.actions form{margin:0}.action-icon{width:36px;height:36px;padding:0;border-radius:9px}.action-icon svg{width:17px;height:17px;display:block}.empty{padding:40px;text-align:center;color:#64748b}.modal-backdrop{position:fixed;inset:0;background:#020617b8;backdrop-filter:blur(7px);display:none;align-items:center;justify-content:center;padding:20px;z-index:1000}.modal-backdrop.open{display:flex}.progress-modal{width:min(520px,100%);background:linear-gradient(145deg,#121a2b,#0d1423);border:1px solid #2b3a52;border-radius:22px;box-shadow:0 30px 90px #0008;padding:26px}.modal-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:24px}.modal-eyebrow{font-size:11px;color:#7dd3fc;font-weight:850;text-transform:uppercase;letter-spacing:.1em}.modal-title{font-size:22px;font-weight:850;margin-top:5px}.modal-client{font-size:12px;color:#64748b;margin-top:4px}.modal-close{width:38px;height:38px;border:1px solid #2b3a52;border-radius:10px;background:#172033;color:#cbd5e1;font-size:20px;cursor:pointer}.modal-close:hover{background:#1e293b;color:#fff}.modal-progress-box{background:#0a1120;border:1px solid #2b3a52;border-radius:16px;padding:20px}.modal-progress-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.modal-progress-label{font-size:12px;color:#cbd5e1;font-weight:850;text-transform:uppercase;letter-spacing:.08em}.modal-progress-value{font-size:30px;font-weight:900;color:#7dd3fc}.modal-slider{width:100%;height:10px;appearance:none;-webkit-appearance:none;border-radius:99px;background:linear-gradient(to right,#38bdf8 0%,#38bdf8 var(--progress),#1e293b var(--progress),#1e293b 100%);outline:none;cursor:pointer}.modal-slider::-webkit-slider-thumb{appearance:none;-webkit-appearance:none;width:23px;height:23px;border-radius:50%;background:#fff;border:3px solid #38bdf8}.modal-slider::-moz-range-thumb{width:17px;height:17px;border-radius:50%;background:#fff;border:3px solid #38bdf8}.modal-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.saving{opacity:.7;pointer-events:none}@media(max-width:760px){.wrap{padding:18px}.card-header{align-items:flex-start;flex-direction:column}.card-header-actions{width:100%;flex-wrap:wrap}.card-header-actions .btn{flex:1}.modal-actions{flex-direction:column}.modal-actions .btn{width:100%}}
</style>
